use rk3588_boot_support::{CacheRangeOps,MemoryTransfer,Mmio32};
pub const PMUMCU_LIVE_BASE:u64=0xFF08_0000;pub const PMUMCU_BACKUP_BASE:u64=0x0000_1000;pub const PMUMCU_MAGIC_ADDR:u64=0xFF08_0140;pub const PMUMCU_SENTINEL_ADDR:u64=0xFF08_0148;pub const PMUMCU_MAGIC:u32=0x5F4D_4355;pub const PMUMCU_SENTINEL:u32=0xDEAD_BEAF;
/// Binary-exact units are intentionally distinct: `sub_6F580` interprets 0x17C00
/// as a DWORD count, while `sub_796E8` interprets the same literal as bytes.
pub const PMUMCU_COPY_WORDS:u32=0x0001_7C00;pub const PMUMCU_CACHE_BYTES:u32=0x0001_7C00;pub const PMUMCU_COPY_BYTES:u32=PMUMCU_COPY_WORDS*4;
pub fn save_pmumcu_image<I:Mmio32+MemoryTransfer+CacheRangeOps>(io:&mut I)->bool{if io.read32(PMUMCU_MAGIC_ADDR)!=PMUMCU_MAGIC||io.read32(PMUMCU_SENTINEL_ADDR)!=PMUMCU_SENTINEL{return false}io.copy_words_exact(PMUMCU_BACKUP_BASE,PMUMCU_LIVE_BASE,PMUMCU_COPY_WORDS);io.clean_invalidate_range(PMUMCU_BACKUP_BASE,PMUMCU_CACHE_BYTES);true}
pub fn restore_pmumcu_image<I:MemoryTransfer>(io:&mut I,enabled:bool,saved:bool)->bool{if enabled&&saved{io.copy_words_exact(PMUMCU_LIVE_BASE,PMUMCU_BACKUP_BASE,PMUMCU_COPY_WORDS);true}else{false}}
#[cfg(test)]mod tests{use super::*;struct M{magic:u32,sentinel:u32,copy:(u64,u64,u32),cache:(u64,u32)}impl Mmio32 for M{fn read32(&mut self,a:u64)->u32{if a==PMUMCU_MAGIC_ADDR{self.magic}else if a==PMUMCU_SENTINEL_ADDR{self.sentinel}else{0}}fn write32(&mut self,_:u64,_:u32){}}impl MemoryTransfer for M{fn copy_words_exact(&mut self,d:u64,s:u64,w:u32){self.copy=(d,s,w)}}impl CacheRangeOps for M{fn clean_invalidate_range(&mut self,a:u64,b:u32){self.cache=(a,b)}}#[test]fn units(){let mut m=M{magic:PMUMCU_MAGIC,sentinel:PMUMCU_SENTINEL,copy:(0,0,0),cache:(0,0)};assert!(save_pmumcu_image(&mut m));assert_eq!(m.copy,(PMUMCU_BACKUP_BASE,PMUMCU_LIVE_BASE,0x17C00));assert_eq!(m.cache,(PMUMCU_BACKUP_BASE,0x17C00));assert_eq!(PMUMCU_COPY_BYTES,0x5F000);assert!(restore_pmumcu_image(&mut m,true,true));assert_eq!(m.copy.0,PMUMCU_LIVE_BASE);}}
